  if (error) return { ok: false, ...error };
  const id = cuerpo && cuerpo.contact && cuerpo.contact.id;
  if (!id) return { ok: false, motivo: 'respuesta_invalida', reintentable: false, detalle: 'La respuesta no incluye contact.id' };
